CREATE TABLE transactions (
    id UUID PRIMARY KEY,
    user_id BIGINT NOT NULL,
    account_id BIGINT NOT NULL,
    merchant_id BIGINT NOT NULL,
    status VARCHAR(32) NOT NULL,
    amount NUMERIC(15, 2) NOT NULL,
    currency VARCHAR(3) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL
);

-- BUG: Redundant and overlapping B-Tree indexes multiplying write cost by 8x
CREATE INDEX idx_tx_user ON transactions(user_id);
CREATE INDEX idx_tx_user_created ON transactions(user_id, created_at);
CREATE INDEX idx_tx_account ON transactions(account_id);
CREATE INDEX idx_tx_merchant ON transactions(merchant_id);
CREATE INDEX idx_tx_status ON transactions(status); -- Low cardinality index
CREATE INDEX idx_tx_created ON transactions(created_at);
CREATE INDEX idx_tx_currency ON transactions(currency); -- 3 distinct values only
CREATE INDEX idx_tx_amount ON transactions(amount);

